import{_ as e,o as d,c as r,a4 as n}from"./chunks/framework.BMj-uaUw.js";const g=JSON.parse('{"title":"案例总览","description":"","frontmatter":{},"headers":[{"level":2,"title":"案例库是做什么的","slug":"案例库是做什么的","link":"#案例库是做什么的","children":[]},{"level":2,"title":"每个案例长什么样","slug":"每个案例长什么样","link":"#每个案例长什么样","children":[]},{"level":2,"title":"怎么用这套案例（三步法）","slug":"怎么用这套案例-三步法","link":"#怎么用这套案例-三步法","children":[{"level":3,"title":"第一步：只读前半段，读完就停","slug":"第一步-只读前半段-读完就停","link":"#第一步-只读前半段-读完就停","children":[]},{"level":3,"title":"第二步：自己写一版，允许写得很丑","slug":"第二步-自己写一版-允许写得很丑","link":"#第二步-自己写一版-允许写得很丑","children":[]},{"level":3,"title":"第三步：对照“完整代码”和“常见坑”","slug":"第三步-对照-完整代码-和-常见坑","link":"#第三步-对照-完整代码-和-常见坑","children":[]}]},{"level":2,"title":"难度分级说明","slug":"难度分级说明","link":"#难度分级说明","children":[]},{"level":2,"title":"10 个案例一览","slug":"_10-个案例一览","link":"#_10-个案例一览","children":[]},{"level":2,"title":"案例和单元怎么配合","slug":"案例和单元怎么配合","link":"#案例和单元怎么配合","children":[]},{"level":2,"title":"完成一个案例的验收标准","slug":"完成一个案例的验收标准","link":"#完成一个案例的验收标准","children":[]},{"level":2,"title":"案例和综合项目的关系","slug":"案例和综合项目的关系","link":"#案例和综合项目的关系","children":[]},{"level":2,"title":"案例里统一的几个约定","slug":"案例里统一的几个约定","link":"#案例里统一的几个约定","children":[]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[]}],"relativePath":"cases/index.md","filePath":"cases/index.md","lastUpdated":1789307994000}'),a={name:"cases/index.md"};function i(l,t,o,s,h,c){return d(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="案例总览" tabindex="-1">案例总览 <a class="header-anchor" href="#案例总览" aria-label="Permalink to &quot;案例总览&quot;">​</a></h1><h2 id="案例库是做什么的" tabindex="-1">案例库是做什么的 <a class="header-anchor" href="#案例库是做什么的" aria-label="Permalink to &quot;案例库是做什么的&quot;">​</a></h2><p>前面 12 个单元按知识点组织：一个单元讲清一类能力，每节配一个小示例。这样安排的好处是每条线都清楚， 但真实项目不会按知识点出题 —— 一个页面往往同时用到列表渲染、表单绑定、接口请求和状态管理。</p><p>案例库补的就是这一段：<strong>把多个知识点装进一个完整页面，从数据结构一路写到可运行的代码。</strong></p><p>每个案例都是独立成篇的完整实现，不是单元内容的缩写版。你可以把它当成一份“参考实现 + 讲解”： 先看要做什么，然后自己动手写，卡住了再回来对照。</p><div class="tip custom-block"><p class="custom-block-title">案例里的业务都来自综合项目</p><p>全部 10 个案例都用 <strong>校园活动服务平台 · 管理端</strong> 的实体：活动、报名记录、场次、场地、学生、 组织者、审核员。你在案例里写过的数据结构，后面做综合项目时可以继续用。</p></div><h2 id="每个案例长什么样" tabindex="-1">每个案例长什么样 <a class="header-anchor" href="#每个案例长什么样" aria-label="Permalink to &quot;每个案例长什么样&quot;">​</a></h2><p>所有案例页都用同一套骨架，方便你跳读：</p><table tabindex="0"><thead><tr><th>段落</th><th>里面有什么</th><th>建议怎么读</th></tr></thead><tbody><tr><td>案例要做什么</td><td>业务场景 + “用到的知识点 → 对应章节”表</td><td>先读，读完停下</td></tr><tr><td>数据结构与接口设计</td><td>先定数据长什么样，再写代码</td><td>想清楚字段再往下</td></tr><tr><td>实现步骤</td><td>分 3 到 6 步，每步一段可运行代码</td><td>跟着写</td></tr><tr><td>完整代码</td><td>可以直接复制进项目的完整文件</td><td>对照自己的版本</td></tr><tr><td>常见坑</td><td>每条“现象 → 原因 → 怎么处理”，默认折叠</td><td>报错时回来查</td></tr><tr><td>扩展练习</td><td>给思路不给答案，默认折叠</td><td>写完基础版再做</td></tr></tbody></table><p>“完整代码”那一段看起来最长，但它只是把前面几步拼起来，不是另写一套。<strong>如果你前面每步都写过了， 这一段应该是用来核对的，不是用来抄的。</strong></p><h2 id="怎么用这套案例-三步法" tabindex="-1">怎么用这套案例（三步法） <a class="header-anchor" href="#怎么用这套案例-三步法" aria-label="Permalink to &quot;怎么用这套案例（三步法）&quot;">​</a></h2><h3 id="第一步-只读前半段-读完就停" tabindex="-1">第一步：只读前半段，读完就停 <a class="header-anchor" href="#第一步-只读前半段-读完就停" aria-label="Permalink to &quot;第一步：只读前半段，读完就停&quot;">​</a></h3><p>读“案例要做什么”和“数据结构与接口设计”，<strong>不要往下翻</strong>。读到“用到的知识点”表时，自己判断一下： 表里这些章节我是不是都学过？有哪一条一看就想不起来？</p><h3 id="第二步-自己写一版-允许写得很丑" tabindex="-1">第二步：自己写一版，允许写得很丑 <a class="header-anchor" href="#第二步-自己写一版-允许写得很丑" aria-label="Permalink to &quot;第二步：自己写一版，允许写得很丑&quot;">​</a></h3><p>先让它跑起来，再想怎么变好看。这一阶段的目标不是写出和参考实现一样的代码，而是 <strong>遇到具体卡点</strong>：数组怎么增删不会错、<code>computed</code> 该怎么联、请求取消写在哪儿。</p><h3 id="第三步-对照-完整代码-和-常见坑" tabindex="-1">第三步：对照“完整代码”和“常见坑” <a class="header-anchor" href="#第三步-对照-完整代码-和-常见坑" aria-label="Permalink to &quot;第三步：对照“完整代码”和“常见坑”&quot;">​</a></h3><p>对照时重点看三件事：</p><ol><li>我的写法和参考实现差在哪，差别是“习惯不同”还是“我漏了一种情况”。</li><li>“常见坑”里有没有我刚刚踩到的，如果有，把原因写进自己的笔记。</li><li>“扩展练习”挑一道做，这一步才是把案例真正变成自己能力的地方。</li></ol><div class="warning custom-block"><p class="custom-block-title">不要跳过第二步</p><p>直接看完整代码看起来很快，但你会发现合上页面什么也没留下。案例的价值不在代码本身， 而在 <strong>你卡住的那几分钟</strong>。</p></div><h2 id="难度分级说明" tabindex="-1">难度分级说明 <a class="header-anchor" href="#难度分级说明" aria-label="Permalink to &quot;难度分级说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>星级</th><th>名称</th><th>判断依据</th><th>需要先掌握</th></tr></thead><tbody><tr><td>★☆☆</td><td>入门</td><td>单页面，没有异步请求，不需要拆组件</td><td>模板语法、<code>ref</code>、<code>v-for</code>、<code>v-model</code></td></tr><tr><td>★★☆</td><td>进阶</td><td>有异步请求，或者要拆组件、要做多层数据派生</td><td>生命周期、<code>computed</code>、<code>watch</code>、props 与 emits</td></tr><tr><td>★★★</td><td>综合</td><td>多个模块协作，需要自己设计状态和数据流</td><td>路由、状态管理、自定义指令、组合式函数</td></tr></tbody></table><p>星级只代表“这个案例需要多少前置知识”，不代表“有多难写对”。★☆☆ 的案例同样有值得琢磨的地方， 比如键值怎么选、空状态怎么处理 —— 这两件事很多人做了两年还在犯错。</p><h2 id="_10-个案例一览" tabindex="-1">10 个案例一览 <a class="header-anchor" href="#_10-个案例一览" aria-label="Permalink to &quot;10 个案例一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>名称</th><th>难度</th><th>涉及知识点</th><th>对应章节</th></tr></thead><tbody><tr><td>01</td><td><a href="/frontend-engineering-course/cases/01-crud.html">增删改查清单</a></td><td>★☆☆</td><td>列表渲染、条件渲染、事件处理、表单绑定</td><td><a href="/frontend-engineering-course/unit05/04-list.html">列表渲染与键值</a> · <a href="/frontend-engineering-course/unit06/03-form-binding.html">表单绑定</a></td></tr><tr><td>02</td><td><a href="/frontend-engineering-course/cases/02-grid.html">可排序筛选的数据表格</a></td><td>★★☆</td><td>计算属性、链式派生、数组排序与分页</td><td><a href="/frontend-engineering-course/unit05/01-computed.html">计算属性与缓存</a> · <a href="/frontend-engineering-course/unit05/04-list.html">列表渲染与键值</a></td></tr><tr><td>03</td><td><a href="/frontend-engineering-course/cases/03-tree.html">树状视图与递归组件</a></td><td>★★☆</td><td>递归组件、扁平转树、选中与半选</td><td><a href="/frontend-engineering-course/unit07/01-sfc.html">单文件组件与拆分依据</a> · <a href="/frontend-engineering-course/unit07/02-props.html">props</a> · <a href="/frontend-engineering-course/unit08/02-provide-inject.html">依赖注入</a></td></tr><tr><td>04</td><td><a href="/frontend-engineering-course/cases/04-fetch.html">从接口获取数据</a></td><td>★★☆</td><td>生命周期、四态页面、请求取消、组合式函数</td><td><a href="/frontend-engineering-course/unit05/05-four-states.html">四态页面规范</a> · <a href="/frontend-engineering-course/unit06/05-lifecycle.html">生命周期与副作用清理</a> · <a href="/frontend-engineering-course/unit10/04-request-layer.html">请求层封装</a></td></tr><tr><td>05</td><td><a href="/frontend-engineering-course/cases/05-markdown.html">Markdown 编辑器</a></td><td>★★☆</td><td><code>v-model</code> 自定义组件、光标操作、防抖</td><td><a href="/frontend-engineering-course/unit06/03-form-binding.html">表单绑定</a> · <a href="/frontend-engineering-course/unit07/04-vmodel.html">组件上的 v-model</a></td></tr><tr><td>06</td><td><a href="/frontend-engineering-course/cases/06-modal.html">模态框与全局通知</a></td><td>★★☆</td><td>插槽、<code>Teleport</code>、依赖注入</td><td><a href="/frontend-engineering-course/unit08/01-slots.html">插槽</a> · <a href="/frontend-engineering-course/unit08/03-builtin.html">内置组件</a></td></tr><tr><td>07</td><td><a href="/frontend-engineering-course/cases/07-wizard.html">多步表单</a></td><td>★★☆</td><td>表单校验、动态组件、跨步骤状态</td><td><a href="/frontend-engineering-course/unit06/04-validation.html">表单校验</a> · <a href="/frontend-engineering-course/unit08/02-provide-inject.html">依赖注入</a></td></tr><tr><td>08</td><td><a href="/frontend-engineering-course/cases/08-canvas.html">画板与撤销重做</a></td><td>★★★</td><td>自定义指令、指针事件、快照与命令模式</td><td><a href="/frontend-engineering-course/unit08/05-directives.html">自定义指令</a> · <a href="/frontend-engineering-course/unit06/05-lifecycle.html">生命周期与副作用清理</a></td></tr><tr><td>09</td><td><a href="/frontend-engineering-course/cases/09-editable-table.html">可编辑表格</a></td><td>★★★</td><td>组件通信、编辑态管理、列表渲染</td><td><a href="/frontend-engineering-course/unit07/02-props.html">props</a> · <a href="/frontend-engineering-course/unit07/03-emits.html">emits</a></td></tr><tr><td>10</td><td><a href="/frontend-engineering-course/cases/10-auth.html">登录与鉴权</a></td><td>★★★</td><td>路由守卫、全局状态、请求层</td><td><a href="/frontend-engineering-course/unit09/03-guards.html">路由守卫</a> · <a href="/frontend-engineering-course/unit10/02-pinia-basics.html">Pinia 两种写法</a></td></tr></tbody></table><h2 id="案例和单元怎么配合" tabindex="-1">案例和单元怎么配合 <a class="header-anchor" href="#案例和单元怎么配合" aria-label="Permalink to &quot;案例和单元怎么配合&quot;">​</a></h2><p>案例不是“单元课后练习的升级版”，它和单元是两种不同的读法：</p><table tabindex="0"><thead><tr><th>维度</th><th>单元章节</th><th>案例页</th></tr></thead><tbody><tr><td>组织方式</td><td>按知识点</td><td>按完整功能</td></tr><tr><td>读法</td><td>顺序读，每节独立</td><td>先自己写，再对照</td></tr><tr><td>代码形态</td><td>片段，够说明问题就行</td><td>完整文件，能直接复制运行</td></tr><tr><td>主要作用</td><td>建立概念</td><td>建立手感</td></tr></tbody></table><p>如果时间紧，可以按下面的顺序走：先跟着单元学知识点，每学完一个单元，挑一个对应该单元的案例做一遍。</p><table tabindex="0"><thead><tr><th>学完这些单元</th><th>建议做</th></tr></thead><tbody><tr><td>单元 4、5、6</td><td>案例 01 → 案例 02</td></tr><tr><td>单元 7、8</td><td>案例 03 → 案例 05 → 案例 06</td></tr><tr><td>单元 9、10</td><td>案例 04 → 案例 10</td></tr><tr><td>单元 11、12</td><td>案例 07、08、09 全部做一遍</td></tr></tbody></table><h2 id="完成一个案例的验收标准" tabindex="-1">完成一个案例的验收标准 <a class="header-anchor" href="#完成一个案例的验收标准" aria-label="Permalink to &quot;完成一个案例的验收标准&quot;">​</a></h2><p>写完一个案例，用这张表自查。五条全过，才算真的做完。</p><ul><li>[ ] 页面能跑起来，控制台没有报错和警告。</li><li>[ ] 空数据、加载失败这两种情况都有对应的界面，不是一片空白。</li><li>[ ] 列表渲染用了稳定的键值，没有拿数组下标当键。</li><li>[ ] 所有需要用户等待或确认的操作都有反馈（按钮禁用、二次确认、提示文案）。</li><li>[ ] 能用自己的话讲清这个案例里“最麻烦的一个点”是什么，以及为什么这样处理。</li></ul><h2 id="案例和综合项目的关系" tabindex="-1">案例和综合项目的关系 <a class="header-anchor" href="#案例和综合项目的关系" aria-label="Permalink to &quot;案例和综合项目的关系&quot;">​</a></h2><p>综合项目的五个模块，在案例库里都能找到对应的零件：</p><table tabindex="0"><thead><tr><th>综合项目模块</th><th>可以直接参考的案例</th></tr></thead><tbody><tr><td>登录鉴权</td><td>案例 10</td></tr><tr><td>活动管理</td><td>案例 01、案例 09</td></tr><tr><td>报名审核</td><td>案例 02、案例 04、案例 05</td></tr><tr><td>场次与场地</td><td>案例 01、案例 07</td></tr><tr><td>数据看板</td><td>案例 02、案例 08</td></tr></tbody></table><p>零件不等于成品。综合项目还要把这些页面接到路由、全局状态和权限控制上， 那部分在<a href="/frontend-engineering-course/unit11/01-requirements.html">单元 11 的需求梳理</a>和<a href="/frontend-engineering-course/unit12/01-integration.html">单元 12 的前后端联调</a>里讲。</p><h2 id="案例里统一的几个约定" tabindex="-1">案例里统一的几个约定 <a class="header-anchor" href="#案例里统一的几个约定" aria-label="Permalink to &quot;案例里统一的几个约定&quot;">​</a></h2><p>10 个案例由不同的章节引出，但写法上保持一致，这样你在案例之间跳读时不用重新适应：</p><table tabindex="0"><thead><tr><th>项目</th><th>约定</th><th>原因</th></tr></thead><tbody><tr><td>组件写法</td><td><code>&lt;script setup&gt;</code> + 组合式 API</td><td>与 Vue 3.5 的推荐写法一致</td></tr><tr><td>组件命名</td><td>文件名用大驼峰，如 <code>SignupGrid.vue</code></td><td>模板里可以直接用 <code>&lt;SignupGrid /&gt;</code></td></tr><tr><td>样式</td><td><code>&lt;style scoped&gt;</code>，只写满足功能的最少样式</td><td>避免样式问题盖过知识点</td></tr><tr><td>界面元素</td><td>用原生标签，不引入 UI 组件库</td><td>少一层依赖，代码能直接看懂</td></tr><tr><td>数据来源</td><td>本地假数据或本地 mock，接口形状按真实约定写</td><td>现在就能跑，接后端时改动最小</td></tr><tr><td>注释</td><td>只写在“为什么这样做”的地方</td><td>代码本身已经说明了“做了什么”</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">关于“不引入 UI 组件库”</p><p>综合项目里会用 Element Plus，那样开发更快。但案例的目的是让你看清实现过程 —— 如果一个表格的排序逻辑被组件库封装成一行 <code>:sortable</code>，你就学不到 <code>computed</code> 怎么分层。 <strong>先用原生写一遍，再用组件库，你会知道组件库替你做了什么。</strong></p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><details class="details custom-block"><summary>案例代码可以直接用在综合项目里吗</summary><p>可以，但要改两处：</p><ol><li><strong>数据来源</strong>。案例为了让代码能直接运行，多数用本地假数据或本地 mock；综合项目里要换成 真实的接口调用，参考<a href="/frontend-engineering-course/cases/04-fetch.html">案例 04</a>里的 api 分层写法。</li><li><strong>样式</strong>。案例的样式只保证能用，没有做主题变量和响应式；项目里建议把颜色、间距抽成 CSS 变量，具体做法在<a href="/frontend-engineering-course/unit02/04-vite.html">单元 2 的样式部分</a>。</li></ol><p>直接复制不改，最常见的结果是：案例能跑，项目里报一堆样式冲突。</p></details><details class="details custom-block"><summary>一个案例要花多久</summary><p>不要按时间规划，按“卡点数量”规划。一个 ★☆☆ 案例通常只有两三个真正的卡点， ★★★ 的案例可能有七八个。<strong>卡点解掉就是有效学习时间，抄代码不算。</strong></p><p>如果某个案例你已经能在不看参考实现的情况下一次写完，说明这个知识点已经掌握，直接跳过下一个。</p></details><details class="details custom-block"><summary>案例里的写法和我看到的不一样</summary><p>可能是三种情况，需要分别对待：</p><ol><li><strong>风格差异</strong>：比如用 <code>computed</code> 还是 <code>watch</code> 都能实现，都能跑。这种情况看哪种更容易讲清数据流。</li><li><strong>版本差异</strong>：本课程基线是 Vue 3.5.42，网上大量文章还在讲 Vue 2 的 <code>this</code>、<code>$set</code>， 那些写法在组合式 API 里已经不适用。</li><li><strong>案例写错了</strong>：如果确实有 bug，按<a href="/frontend-engineering-course/cases/04-fetch.html">案例 04</a>里“竞态”那一节的思路验证一遍， 能复现就能定位。</li></ol><p>判断标准只有一条：<strong>哪种写法更能说清数据从哪来、到哪去。</strong></p></details><hr><p>下一页：<a href="/frontend-engineering-course/cases/01-crud.html">案例 01 · 增删改查清单</a></p>',46)])])}const f=e(a,[["render",i]]);export{g as __pageData,f as default};
